<?php
declare(strict_types=1);
require_once dirname(__DIR__,2) . '/includes/app/bootstrap.php';
require_permission('users.view');
$directoryUsers=data_admin_visible_users();$users=$directoryUsers;$search=strtolower(query_string('q'));$status=query_string('status');$role=query_string('role');$company=query_int('company');
$users=array_values(array_filter($users,static function(array $u)use($search,$status,$role,$company):bool{if($search!==''&&!str_contains(strtolower($u['name'].' '.$u['email'].' '.$u['job_title'].' '.$u['department']),$search))return false;if($status!==''&&$u['status']!==$status)return false;if($role!==''&&!in_array($role,$u['role_codes'],true))return false;if($company&& !in_array($company,array_map('intval',$u['company_ids']),true))return false;return true;}));
$users=sort_records($users,'name');$pagination=paginate_records($users,query_int('page',1),8);
$actions=can('users.create')?'<button class="button primary" data-modal-open="userModal" type="button">Create User</button>':'';
render_app_start('Users','admin-users','Identity administration','Search, create, view, edit, suspend, archive, restore, assign roles, set companies, and revoke sessions.',$actions);
?>
<section class="metric-grid metric-grid-4"><article class="metric-card"><span>Total users</span><strong><?= count($directoryUsers) ?></strong><small>Accounts within this administrator’s company scope</small></article><article class="metric-card"><span>Active</span><strong><?= count(array_filter($directoryUsers,fn($u)=>$u['status']==='active')) ?></strong><small>Can sign in</small></article><article class="metric-card"><span>Suspended</span><strong><?= count(array_filter($directoryUsers,fn($u)=>$u['status']==='suspended')) ?></strong><small>Temporarily blocked</small></article><article class="metric-card"><span>Reset required</span><strong><?= count(array_filter($directoryUsers,fn($u)=>!empty($u['require_password_reset']))) ?></strong><small>Next sign-in requirement</small></article></section>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">User directory</span><h2>Accounts and access</h2></div><span class="panel-meta"><?= $pagination['total'] ?> matching users</span></header><form class="filter-bar wide-filter" method="get"><label><span>Search</span><input name="q" value="<?= h(query_string('q')) ?>" placeholder="Name, email, title, department"></label><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach(['active','suspended','archived'] as $value): ?><option value="<?= h($value) ?>" <?= $status===$value?'selected':'' ?>><?= h(status_label($value)) ?></option><?php endforeach; ?></select></label><label><span>Role</span><select name="role"><option value="">All roles</option><?php foreach(data_collection('roles') as $r): ?><option value="<?= h($r['code']) ?>" <?= $role===$r['code']?'selected':'' ?>><?= h($r['name']) ?></option><?php endforeach; ?></select></label><label><span>Company</span><select name="company"><option value="0">All companies</option><?= company_options($company) ?></select></label><button class="button secondary" type="submit">Apply filters</button><a class="button ghost" href="<?= h(app_url('admin/users.php')) ?>">Reset</a></form><div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Title / department</th><th>Primary company</th><th>Roles</th><th>Status</th><th>Last login</th><th>Administrative actions</th></tr></thead><tbody><?php foreach($pagination['items'] as $account): ?><tr><td><a class="user-cell" href="<?= h(app_url('admin/user.php?id='.(int)$account['id'])) ?>"><span class="avatar"><?= h(initials($account['name'])) ?></span><span><strong><?= h($account['name']) ?></strong><small><?= h($account['email']) ?></small></span></a></td><td><?= h($account['job_title']) ?><small><?= h($account['department']) ?></small></td><td><?= h(data_company_name($account['primary_company_id'])) ?><small><?= count($account['company_ids']) ?> membership(s)</small></td><td><div class="tag-list"><?php foreach($account['role_codes'] as $code): ?><span><?= h(data_role_name($code)) ?></span><?php endforeach; ?></div></td><td><?= badge($account['status']) ?><?php if($account['require_password_reset']): ?><small><?= badge('reset_required','Reset required') ?></small><?php endif; ?></td><td><?= h(date_us($account['last_login'],true)) ?></td><td><div class="row-actions"><a class="mini-button secondary" href="<?= h(app_url('admin/user.php?id='.(int)$account['id'])) ?>">View / edit</a><?php if(can('users.edit')&&(int)$account['id']!==(int)current_user()['id']): $next=$account['status']==='active'?'suspended':'active'; ?><form action="<?= h(app_url('action.php')) ?>" method="post" data-confirm="Change this user to <?= h(status_label($next)) ?>?"><?= csrf_field() ?><input type="hidden" name="action" value="user_status"><input type="hidden" name="id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="status" value="<?= h($next) ?>"><input type="hidden" name="return_to" value="admin/users.php"><button class="mini-button <?= $next==='active'?'primary':'ghost' ?>" type="submit"><?= $next==='active'?'Activate':'Suspend' ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?= render_pagination($pagination,['q'=>query_string('q'),'status'=>$status,'role'=>$role,'company'=>$company]) ?></section>
<?php if(can('users.create')): ?><div class="modal" id="userModal" hidden><div class="modal-backdrop" data-modal-close></div><section class="modal-card modal-card-wide"><header><div><span class="eyebrow">New account</span><h2>Create user</h2></div><button type="button" data-modal-close>×</button></header><form class="modal-body form-grid" action="<?= h(app_url('action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_user"><input type="hidden" name="return_to" value="admin/users.php"><label><span>First name</span><input name="first_name" required></label><label><span>Last name</span><input name="last_name" required></label><label><span>Email</span><input type="email" name="email" required></label><label><span>Phone</span><input name="phone"></label><label><span>Job title</span><input name="job_title"></label><label><span>Department</span><input name="department"></label><label><span>Status</span><select name="status"><option value="active">Active</option><option value="suspended">Suspended</option></select></label><label><span>Primary company</span><select name="primary_company_id"><?= company_options(1) ?></select></label><div class="span-2"><span class="field-label">Company memberships</span><?= company_checkbox_grid([1]) ?></div><div class="span-2"><span class="field-label">Roles</span><?= role_checkbox_grid(['read_only']) ?></div><label class="span-2"><span>Administrative notes</span><textarea name="admin_notes" rows="3"></textarea></label><label class="span-2 toggle-row"><span><strong>Require password reset</strong><small>The user must reset their password at the next production sign-in.</small></span><input type="checkbox" name="require_password_reset" checked></label><div class="span-2 modal-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary" type="submit">Create user</button></div></form></section></div><?php endif; ?>
<?php render_app_end(); ?>
